const ASSETS={"/assets/map.js":"(() => {\n  if (!window.L) return;\n  document.querySelectorAll('.map').forEach(el => {\n    const d = JSON.parse(el.querySelector('.mapdata').textContent);\n    const m = L.map(el, { scrollWheelZoom: false }).setView(d.c, d.z);\n    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '&copy; <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a> contributors' }).addTo(m);\n    const esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n    const pts = [];\n    d.pins.forEach(p => {\n      const icon = L.divIcon({ className: 'pin ' + p.k, html: '<span></span>', iconSize: [18, 18], iconAnchor: [9, 9] });\n      L.marker(p.p, { icon, title: p.n }).addTo(m).bindPopup(`<strong><a href=\"${esc(p.u)}\">${esc(p.n)}</a></strong><br>${esc(p.a)}<br><a href=\"${esc(p.g)}\" target=\"_blank\" rel=\"noopener\">Google</a> · <a href=\"${esc(p.ap)}\" target=\"_blank\" rel=\"noopener\">Apple</a> · <a href=\"${esc(p.w)}\" target=\"_blank\" rel=\"noopener\">Waze</a>`);\n      pts.push(p.p);\n    });\n    if (pts.length > 1 && d.pins.length < 40) m.fitBounds(pts, { padding: [30, 30], maxZoom: 18 });\n  });\n})();\n","/assets/tonight.js":"(() => {\n  const el = document.getElementById('tonight'), data = JSON.parse(document.getElementById('otdata').textContent);\n  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/London', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());\n  const get = t => (parts.find(x => x.type === t) || {}).value;\n  const days = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];\n  const today = days.indexOf(get('weekday').toLowerCase().slice(0, 3)); const now = (+get('hour') % 24) * 60 + +get('minute');\n  const mins = s => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };\n  const status = h => {\n    const yest = h[days[(today + 6) % 7]], tod = h[days[today]];\n    const parse = r => { const m = /^(\\d\\d:\\d\\d)\\s*-\\s*(\\d\\d:\\d\\d)/.exec(r || ''); if (!m) return null; let a = mins(m[1]), b = mins(m[2]); if (b <= a) b += 1440; return [a, b]; };\n    const y = parse(yest); if (y && now + 1440 < y[1]) return ['open', 'Open now, until ' + yest.split('-')[1].trim()];\n    const t = parse(tod); if (!t) return ['closed', 'Not listed as open today'];\n    if (now >= t[0] && now < t[1]) return ['open', 'Open now, until ' + tod.split('-')[1].trim()];\n    if (now < t[0]) return ['later', 'Opens ' + tod.split('-')[0].trim()];\n    return ['closed', 'Closed for the night'];\n  };\n  const rows = Object.values(data).map(v => ({ ...v, s: status(v.h) }));\n  const order = { open: 0, later: 1, closed: 2 }; rows.sort((a, b) => order[a.s[0]] - order[b.s[0]] || a.n.localeCompare(b.n));\n  const esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n  el.innerHTML = '<p class=\"small\">Checked at ' + get('hour') + ':' + get('minute') + ' UK time, from listed hours.</p><ul class=\"otlist\">' + rows.map(r => `<li class=\"${r.s[0]}\"><a href=\"${esc(r.u)}\">${esc(r.n)}</a><span>${esc(r.s[1])}</span><em>${esc(r.k)}</em></li>`).join('') + '</ul>';\n})();\n","/assets/forum.js":"(() => {\n  const esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n  document.querySelectorAll('.posts').forEach(async box => {\n    try { const r = await fetch('/api/forum/' + box.dataset.topic); const j = await r.json();\n      box.innerHTML = (j.posts || []).length ? j.posts.map(p => `<div class=\"post\"><strong>${esc(p.name)}</strong> <span class=\"small\">${esc((p.at || '').slice(0, 10))}</span><p>${esc(p.body)}</p></div>`).join('') : '<p class=\"small\">No approved posts yet. Be the first.</p>';\n    } catch (e) { box.innerHTML = ''; }\n  });\n  document.querySelectorAll('.postform').forEach(f => {\n    const hp = document.createElement('input'); hp.name = 'website'; hp.tabIndex = -1; hp.autocomplete = 'off'; hp.className = 'hp'; f.appendChild(hp);\n    f.addEventListener('submit', async e => {\n      e.preventDefault(); const st = f.querySelector('.status'); st.textContent = 'Sending…';\n      try { const r = await fetch('/api/forum/' + f.dataset.topic, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: f.name.value, body: f.body.value, website: hp.value }) });\n        const j = await r.json(); st.textContent = j.message || j.error || 'Sent.'; if (r.ok) f.reset();\n      } catch (err) { st.textContent = 'Could not send. Please try again.'; }\n    });\n  });\n})();\n","/favicon.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" rx=\"14\" fill=\"#14111f\"/><g transform=\"translate(8 14)\"><rect width=\"48\" height=\"6\" fill=\"#e40303\"/><rect y=\"6\" width=\"48\" height=\"6\" fill=\"#ff8c00\"/><rect y=\"12\" width=\"48\" height=\"6\" fill=\"#ffed00\"/><rect y=\"18\" width=\"48\" height=\"6\" fill=\"#008026\"/><rect y=\"24\" width=\"48\" height=\"6\" fill=\"#004dff\"/><rect y=\"30\" width=\"48\" height=\"6\" fill=\"#750787\"/></g></svg>\n"};
